"""Konfigurationszugriff fuer Secrets und Umgebungswerte.

Das Modul stellt typisierte Getter bereit, die Secrets erst beim konkreten
Funktionsaufruf entschluesseln. Reine Modulimporte bleiben dadurch frei von
Secret-Zugriffen.
"""

import os
from dataclasses import dataclass

from .auth.secrets_service import decode_secret

_environment_loaded = False


@dataclass(frozen=True)
class DatabaseConfig:
    """Konfiguration fuer eine MariaDB-Verbindung."""

    host: str
    user: str
    password: str
    port: int


@dataclass(frozen=True)
class SftpConfig:
    """Konfiguration fuer eine SFTP-Verbindung."""

    host: str
    port: int
    username: str
    password: str
    remote_path: str


@dataclass(frozen=True)
class EsuiteApiConfig:
    """Konfiguration fuer eine eSuite-API-Umgebung."""

    headers: dict[str, str]
    resthost: str


def get_required_env(name: str, *, context: str) -> str:
    """Liest eine erforderliche Umgebungsvariable mit klarer Fehlermeldung."""
    ensure_environment_loaded()
    value = os.getenv(name)
    if not value:
        raise RuntimeError(f"Erforderliche Umgebungsvariable fehlt fuer {context}: {name}")
    return value


def get_int_env(name: str, default: int, *, context: str) -> int:
    """Liest eine optionale Integer-Umgebungsvariable."""
    ensure_environment_loaded()
    value = os.getenv(name)
    if value is None or value == "":
        return default
    try:
        return int(value)
    except ValueError as exc:
        raise RuntimeError(f"Ungueltiger Integer-Wert fuer {context}: {name}={value!r}") from exc


def decode_required_secret(name: str, *, context: str) -> str:
    """Entschluesselt ein erforderliches Secret mit fachlicher Fehlermeldung."""
    ensure_environment_loaded()
    if not os.getenv(name):
        raise RuntimeError(f"Erforderliches Secret fehlt fuer {context}: {name}")
    try:
        return decode_secret(name)
    except Exception as exc:
        raise RuntimeError(f"Secret konnte nicht entschluesselt werden fuer {context}: {name}") from exc


def get_database_config() -> DatabaseConfig:
    """Laedt die DB-Konfiguration aus Umgebung und Secret-Store."""
    context = "Datenbankverbindung"
    return DatabaseConfig(
        host=get_required_env("DB_HOST", context=context),
        user=decode_required_secret("DB_USER_ENC", context=context),
        password=decode_required_secret("DB_PASSWORD_ENC", context=context),
        port=get_int_env("DB_PORT", 3306, context=context),
    )


def ensure_environment_loaded() -> None:
    """Laedt die gemeinsame Umgebungskonfiguration hoechstens einmal."""
    global _environment_loaded
    if _environment_loaded:
        return

    from .constants import load_shared_environment

    load_shared_environment()
    _environment_loaded = True


def get_esuite_headers(environment: str) -> dict[str, str]:
    """Erstellt eSuite-API-Header fuer PROD oder UAT."""
    environment_name = environment.upper()
    if environment_name == "PROD":
        password_secret = "ESUITE_API_PASSWORD_PROD_ENC"
    elif environment_name == "UAT":
        password_secret = "ESUITE_API_PASSWORD_UAT_ENC"
    else:
        raise ValueError(f"Unbekannte eSuite-Umgebung: {environment}")

    return {
        "X-ClientId": "6027",
        "X-ClientPassword": decode_required_secret(password_secret, context=f"eSuite {environment_name}"),
        "X-Version": "11.37",
        "Content-Type": "application/json",
        "X-PageNumber": "1",
        "X-ResultsPerPage": "1000",
    }


def get_esuite_api_config(environment: str) -> EsuiteApiConfig:
    """Laedt Header und Basis-URL fuer eine eSuite-API-Umgebung."""
    from .constants import RESTHOST_PROD, RESTHOST_UAT

    environment_name = environment.upper()
    if environment_name == "PROD":
        resthost = RESTHOST_PROD
    elif environment_name == "UAT":
        resthost = RESTHOST_UAT
    else:
        raise ValueError(f"Unbekannte eSuite-Umgebung: {environment}")

    return EsuiteApiConfig(headers=get_esuite_headers(environment_name), resthost=resthost)


def get_sftp_account_config() -> SftpConfig:
    """Laedt die SFTP-Konfiguration fuer AccountReport-Uploads."""
    from .constants import REMOTE_SFTP_PATH_ACC

    context = "SFTP AccountReport"
    return SftpConfig(
        host=get_required_env("SFTP_HOST_ACC", context=context),
        port=get_int_env("SFTP_PORT_ACC", 22, context=context),
        username=get_required_env("SFTP_USERNAME_ACC", context=context),
        password=decode_required_secret("SFTP_PASSWORD_ACC_ENC", context=context),
        remote_path=REMOTE_SFTP_PATH_ACC,
    )


